  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (319::BIGINT, 'te quiero mucho kenneth'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2026-06-10T00:00:00+00:00'::TIMESTAMPTZ, '9e0504dd432353f4df12d4affebe7a1d3e36897b9d352726ee99c28c3070260c'::TEXT, ARRAY[1043]::BIGINT[]),
    (319::BIGINT, 'Excelente profesor que explica tod súper bien y las evaluaciones demasiado interesantes. No se arrepentirá de llevar un curso con él, de lo mejor que hay en la carrera.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, '23d362b390e7f14a87d66fd8c7770342d85a8185f6dc226093e943d843ee8e8a'::TEXT, ARRAY[1154]::BIGINT[]),
    (319::BIGINT, 'Increible profesor, realmente no necesita ser profe, lo es porque le gusta enseñar, y se nota, excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'b31849d2464f102947ce468d5c8a1e470388e978a58813ec227b0b5ba11c0c7a'::TEXT, ARRAY[1035]::BIGINT[]),
    (319::BIGINT, 'De los mejores profes de compu, prepárese para aprender bastante, si bien se vuelve algo pesado por todas las tecnologías y materia que el profe quiere ver, vale completamente la pena porque realmente lo prepara a uno solo es cuestion de esforzarse, volvería a matricular con él sin dudarlo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '1c012a24d9db429cd8232db9fcbc81be1cc8679ccd6b00090b408bd5a027913f'::TEXT, ARRAY[1043]::BIGINT[]),
    (319::BIGINT, 'Se nota que el profe sabe muchísimo y explica bien, aunque algo rápido y técnico. Es uno de los profes más amables en compu. El curso en sí es muy pesado, con entregas algo largas y quizes entre medio. Pero en general no es difícil sino más bien cansado.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '49335d2587e139f0772ca5cde973ae8fd10832e1d923c3b18a16f2a1d52f3d07'::TEXT, ARRAY[1043]::BIGINT[]),
    (319::BIGINT, 'El profe es excelente persona, el curso en si es bastante pesado, evalúa de manera justa. Desde semana 4 deja 1 quiz cada 2 semanas presencial. Lo que enseña no es suficiente para entrarle a los proyectos pero sí se aprende mucho. Sabe mucho del ambiente laboral y da buena retroalimentación.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-29T00:00:00+00:00'::TIMESTAMPTZ, '60405b3d76efa96ee850a2436c3148e1e221233d3ac7753a177fad4730d7b832'::TEXT, ARRAY[1043]::BIGINT[]),
    (319::BIGINT, 'Simplemente un excelente profesor en su área, las clases pueden ser complicadas algunas veces pero no tenga miedo de preguntar. Los trabajos son geniales para comprender los conceptos y recuerde estudiar para los quices. Tiene un cronograma que sigue al pie de la letra y es una bella persona :)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'd9fcac1de843de3bfb7d2fc9a0799671153359a850e22f904a7708cfad79db3f'::TEXT, ARRAY[1162]::BIGINT[]),
    (319::BIGINT, 'La mejor opcion para llevar bd definitivamente, el profe ayuda mucho al estudiante, hace clases super dinamicas que hace que uno entienda los temas facilmente. De los mejores profes del TEC'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '646bfe761fffd5a32572994f923b92a0ab1f1ff51284cf5526e7813ba3db8d08'::TEXT, ARRAY[1043]::BIGINT[]),
    (319::BIGINT, 'Excelente profe, enseña muy bien y siempre está dispuesto a ayudar. Hace las clases de una manera distinta a la usual y eso las hace interesantes, además, tiene una forma de pensar muy bonita. 100% recomendado, ni la piense, solo matricule.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '0b70092ec4577ff19e5ce9fd5ba7626d8270ecce2c840b5b076dd87096e72dd9'::TEXT, ARRAY[1043]::BIGINT[]),
    (319::BIGINT, 'El mejor profe para llevar este curso, si tiene interés en el area puede aprender demasiado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '62b327d70b1d41adf5ce7d7141635a88f9e29c6338761145f24948bf2c2638c6'::TEXT, ARRAY[1043]::BIGINT[]),
    (319::BIGINT, 'Llévenlo con el. Es super fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, '8182b5305004e374409d40131850071f762a8b658f7f7f4dbaa0b60619519d43'::TEXT, ARRAY[1162]::BIGINT[]),
    (319::BIGINT, 'Deja tareas livianas que no toman mucho tiempo en terminar y deja recursos para completarlos y los proyectos siguen la misma línea. Con este curso final no es insistente ya que seguro entiende la responsabilidad extra de buscar empresa para práctica y debido a esto es muy muy flexible.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2023-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'b8cd89029015025023ad3cee812944fdd9358bd33b95fbe9ff9ee5af6d5b0b97'::TEXT, ARRAY[1162]::BIGINT[]),
    (319::BIGINT, 'El profe explica muy bien y no califica duro las evaluaciones. Las clases se pueden volver algo pesadas debido a que no deja tantos trabajos en el semestre (al menos en este curso), pero es demasiado pura vida y vale la pena ponerle atención. No dude en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '085a3e85d1f6b814b7e8c7242ebd6ac43741ad93f76053c64d07d6359d4bb8b2'::TEXT, ARRAY[1131]::BIGINT[]),
    (319::BIGINT, 'El profesor deja mucho que desear, solo pasa hablando de wikipedia y ChatGPT. Los temas los dá muy por encima, no es malo como ser humano pero en definitiva las clases virtuales no son lo suyo, en especial que su computadora y calendario laboral AFECTA las lecciones del curso.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f77a7c475944648e65ce1d1bc8489be9a2c06388f24ae01a5a3d7e65c494b8a8'::TEXT, ARRAY[1035]::BIGINT[]),
    (319::BIGINT, 'Excelente calidad de profesor y de persona, ojalá todos fueran como él, la clase se vuelve muy amena. Es de Limón, pero si tengo oportunidad de llevar otro curso con él (remoto) lo matricularía sin ninguna duda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '8870274a85a293e24b7a5b542e3bfc74f16fba39e5f74ece2cad627dce4295a3'::TEXT, ARRAY[1035]::BIGINT[]),
    (319::BIGINT, 'Kenneth es un excelente profesor; llevaría cualquier otro curso con él. Las clases son muy dinámicas y la retroalimentación es buena, también se interesa por que usted aprenda más que solo perder dos horas de su tiempo. No duden en meter con él; es nuevo en la escuela pero de los mejores que hay.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '8d2a843999c24d211bed518dca89ca40c81342a97981dd58cb6c53dc8aff6852'::TEXT, ARRAY[1035]::BIGINT[]),
    (319::BIGINT, 'El profesor es excelente en su enseñanza y brinda una retroalimentación valiosa a sus estudiantes. Su apoyo constante hace que el material sea más fácil de comprender y su pasión por el tema es contagiosa. Sin duda, tomaría su clase otra vez y lo recomendaría a cualquiera que busque un excelente des'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-02-02T00:00:00+00:00'::TIMESTAMPTZ, '0a1e091f2e83d4dcf69b72ad8de046344e7eca0dc28febd0899fb7467a8f3a74'::TEXT, ARRAY[1035]::BIGINT[]),
    (319::BIGINT, 'Es el mejor profe que hay en limón, el curso aunque era de 4 créditos se sintió como uno de 3, explica muy bien la materia, se preocupa por los estudiantes, si ocupa ayuda en algún temas esta disponibles a atender dudas fueras de las horas consultas'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'a3df9a09ff79c922e44c7f1e25575ac49e6ad9907b3cd752df5fcc7acf493cc7'::TEXT, ARRAY[1035]::BIGINT[]),
    (319::BIGINT, 'Es el mejor profe que he tenido, si tiene la oportunidad de llevar algún curso con él no dude en hacerlo, va a aprender bastante con proyectos interesantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'b0952acb3f0f0fc230d49e434bb59521d6330ff886afe5a671439032238ac4ca'::TEXT, ARRAY[1035]::BIGINT[]),
    (319::BIGINT, 'El profe es nuevo, pero no es la primera vez que da clases, es muy pura vida, en el curso dejo varias tareas y dos proyectos que fueron faciles de llevar, además le ayuda a uno con alguna duda que tenga en las tareas y en los proyectos, recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-24T00:00:00+00:00'::TIMESTAMPTZ, '06702f16a34eef8b3f35a10a715eac10bca924dce804bb7f32116a61928f086f'::TEXT, ARRAY[1035]::BIGINT[]),
    (319::BIGINT, 'Es nuevo en la escuela de computación pero es muy buen profe, siempre está dispuesto a ayudar, además que califica bastante bien y justo. Para los proyectos da bastante tiempo, entonces si le pone le va a ir muy bien. El profe es demasiado pura vida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '33f7ca4e4b75475bc7a861c038426fc075c4b0e86a1cba2a8a6499ce91ddacdd'::TEXT, ARRAY[1035]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
